async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }

  const options: SessionListOptions = {
    ...(message.limit !== undefined ? {limit: message.limit} : {}),
    ...(message.before !== undefined ? {before: message.before} : {}),
  };

  try {
    const summaries = await sessionStore.listFor(session.userId, options);
    sendSessionList(ws, summaries.map(toSessionSummaryFrame));
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

function toSessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

